181	function createSubscription(state: State, p: Params): CloneResponse {
182	  const customerId = str(p.customer) ?? "";
183	  const customer = get(state.customers, customerId);
184	  if (!customer) return missing("customer", customerId);
185	  const now = nowFor(state, customerId);
186	  const id = mint(state, "sub");
187	  const items = arr(p.items).map((raw) => {
188	    const it = obj(raw);
189	    return {
190	      id: mint(state, "si"),
191	      price: str(it.price) ?? "",
192	      quantity: num(it.quantity) ?? 1,
193	      created: now,
194	      billed: null,
195	    };
196	  });
197	  for (const it of items) if (!get(state.prices, it.price)) return missing("price", it.price);
198	  const first = items[0];
199	  const interval: Interval = first ? priceOf(state, first.price).interval : "month";
200	  const trialDays = num(p.trial_period_days);
201	  const trialEnd = trialDays !== null ? now + trialDays * 86400 : null;
202	  const mode = str(obj(p.billing_mode).type) === "classic" ? "classic" : "flexible";
203	  const sub: Subscription = {
204	    id,
205	    customer: customerId,
206	    items,
207	    billing_mode: mode,
208	    discounts: [],
209	    anchor: trialEnd ?? now,
210	    period_start: now,
211	    period_end: trialEnd ?? addIntervals(now, interval, 1),
212	    status: trialEnd !== null ? "trialing" : "active",
213	    created: now,
214	    latest_invoice: null,
215	    cancel_at_period_end: false,
216	    cancel_at: null,
217	    canceled_at: null,
218	    ended_at: null,
219	    trial_start: trialEnd !== null ? now : null,
220	    trial_end: trialEnd,
221	    cancellation_reason: null,
222	  };
223	  for (const raw of arr(p.discounts)) {
224	    const coupon = str(obj(raw).coupon) ?? "";
225	    if (!get(state.coupons, coupon)) return missing("coupon", coupon);
226	    sub.discounts.push(newDiscount(state, coupon, customerId, id, now).id);
227	  }
228	  state.subscriptions[id] = sub;
229	  customer.currency ??= "usd";
230	  billFirstInvoice(state, sub, now);
231	  return ok(subscriptionJson(state, sub, false));
232	}
