471	export function handleApi(state: State, req: CloneRequest, p: Params): CloneResponse | null {
472	  const parts = req.path.split("/").filter((s) => s !== "");
473	  if (parts[0] !== "v1") return null;
474	  const [, a, b, c, d] = parts;
475	  const m = req.method;
476	
477	  if (a === "test_helpers" && b === "test_clocks") {
478	    if (m === "POST" && c === undefined) {
479	      const id = mint(state, "clock");
480	      const t = num(p.frozen_time) ?? 0;
481	      state.clocks[id] = { id, frozen_time: t, created: t };
482	      return ok(clockJson(state, id));
483	    }
484	    const clock = c !== undefined ? get(state.clocks, c) : undefined;
485	    if (!clock || c === undefined) return missing("test_clock", c ?? "");
486	    if (m === "GET") return ok(clockJson(state, c));
487	    if (m === "POST" && d === "advance") {
488	      advanceClock(state, clock, num(p.frozen_time) ?? clock.frozen_time);
489	      return ok(clockJson(state, c));
490	    }
491	  }
492	  if (a === "products" && m === "POST" && b === undefined) {
493	    const id = mint(state, "prod");
494	    state.products[id] = { id, name: str(p.name) ?? "" };
495	    return ok({ id, object: "product", name: str(p.name) ?? "", active: true });
496	  }
497	  if (a === "prices" && m === "POST" && b === undefined) {
498	    const id = mint(state, "price");
499	    const interval = str(obj(p.recurring).interval) === "year" ? "year" : "month";
500	    state.prices[id] = {
501	      id,
502	      product: str(p.product) ?? "",
503	      unit_amount: num(p.unit_amount) ?? 0,
504	      currency: str(p.currency) ?? "usd",
505	      interval,
506	      created: Math.max(0, ...Object.values(state.clocks).map((c) => c.frozen_time)),
507	    };
508	    return ok(priceJson(state, id));
509	  }
510	  if (a === "prices" && m === "GET" && b !== undefined) {
511	    return get(state.prices, b) ? ok(priceJson(state, b)) : missing("price", b);
512	  }
513	  if (a === "subscription_items") return subscriptionItems(state, req, p, b);
514	  if (a === "coupons" && m === "POST" && b === undefined) {
515	    const id = mint(state, "coupon");
516	    const coupon = {
517	      id,
518	      percent_off: num(p.percent_off),
519	      amount_off: num(p.amount_off),
520	      duration: str(p.duration) === "once" ? ("once" as const) : ("forever" as const),
521	    };
522	    state.coupons[id] = coupon;
523	    return ok(couponJson(coupon));
524	  }
525	  if (a === "customers") {
526	    if (m === "POST" && b === undefined) {
527	      const id = mint(state, "cus");
528	      const clock = str(p.test_clock);
529	      const now = clock ? (get(state.clocks, clock)?.frozen_time ?? 0) : 0;
530	      const pmToken = str(p.payment_method);
531	      const pm = pmToken ? paymentMethodFrom(state, pmToken, id) : null;
532	      const cus = {
533	        id,
534	        clock,
535	        default_payment_method: pm,
536	        created: now,
537	        balance: 0,
538	        currency: null,
539	        invoice_prefix: invoicePrefix(state.n),
540	        preferred_locales: arr(p.preferred_locales).map((x) => str(x) ?? ""),
541	      };
542	      state.customers[id] = cus;
543	      return ok(customerJson(state, cus));
544	    }
545	    const cus = b !== undefined ? get(state.customers, b) : undefined;
546	    if (!cus || b === undefined) return missing("customer", b ?? "");
547	    if (m === "POST" && c === undefined) {
548	      const dpm = str(obj(p.invoice_settings).default_payment_method);
549	      if (dpm) cus.default_payment_method = paymentMethodFrom(state, dpm, cus.id);
550	    }
551	    return ok(customerJson(state, cus));
552	  }
553	  if (a === "payment_methods" && b !== undefined && c === "attach" && m === "POST") {
554	    const id = paymentMethodFrom(state, b, str(p.customer));
555	    return ok({ id, object: "payment_method", customer: str(p.customer), type: "card" });
556	  }
557	  if (a === "subscriptions") {
558	    if (m === "POST" && b === undefined) return createSubscription(state, p);
559	    if (m === "GET" && b === undefined) return listSubscriptions(state, p);
560	    const sub = b !== undefined ? get(state.subscriptions, b) : undefined;
561	    if (!sub || b === undefined) return missing("subscription", b ?? "");
562	    if (m === "GET") {
563	      // `expand[0]=x` parses to a list, `expand[]=x` to a plain string.
564	      const expand = typeof p.expand === "string" ? [p.expand] : arr(p.expand).map(str);
565	      return ok(
566	        subscriptionJson(
567	          state,
568	          sub,
569	          expand.includes("latest_invoice"),
570	          expand.includes("discounts"),
571	        ),
572	      );
573	    }
574	    if (m === "DELETE") {
575	      cancelNow(state, sub, bool(p.prorate), bool(p.invoice_now));
576	      return ok(subscriptionJson(state, sub, false));
577	    }
578	    if (m === "POST") return updateSubscription(state, sub, p);
579	  }
580	  if (a === "invoices") {
581	    if (m === "POST" && b === "create_preview") return previewInvoice(state, p);
582	    if (m === "GET" && b === "upcoming") return fail(400, UPCOMING_GONE);
583	    if (m === "GET" && b === undefined) return listInvoices(state, p);
584	    if (m === "GET" && b !== undefined) {
585	      const inv = get(state.invoices, b);
586	      return inv ? ok(invoiceJson(state, inv, false)) : missing("invoice", b);
587	    }
588	  }
589	  if (a === "invoiceitems" && m === "GET" && b === undefined) return listInvoiceItems(state, p);
590	  return null;
591	}
