604	function clockJson(state: State, id: string): Json {
605	  const c = get(state.clocks, id);
606	  return {
607	    id,
608	    object: "test_helpers.test_clock",
609	    created: c?.created ?? 0,
610	    frozen_time: c?.frozen_time ?? 0,
611	    livemode: false,
612	    status: "ready",
613	  };
614	}
