205	const ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
206	
207	// Deterministic IDs: the same calls after a reset mint the same IDs.
208	export function mint(state: State, prefix: string): string {
209	  state.n += 1;
210	  const n = state.n;
211	  let x = n * 7919 + 104729;
212	  let s = "";
213	  while (s.length < 14) {
214	    s = (ALPHABET[x % 62] ?? "0") + s;
215	    x = Math.floor(x / 62) + n * 31;
216	  }
217	  // Stripe IDs start with an upper-case letter or digit after the prefix; keep one fixed shape.
218	  return `${prefix}_1${s}`;
219	}
