226	export function nowFor(state: State, customer: string): number {
227	  const c = get(state.customers, customer);
228	  const clock = c?.clock ? get(state.clocks, c.clock) : undefined;
229	  return clock ? clock.frozen_time : Math.floor(Date.now() / 1000);
230	}
