48	// A proration line waiting for the next invoice, as an invoice item created at `now`.
49	export function addPending(
50	  state: State,
51	  sub: Subscription,
52	  line: Omit<Line, "id" | "invoice_item">,
53	  now: number,
54	): string {
55	  const id = mint(state, "ii");
56	  state.invoice_items[id] = {
57	    id,
58	    customer: sub.customer,
59	    subscription: sub.id,
60	    line: { ...line, id: "", invoice_item: id },
61	    invoice: null,
62	    date: now,
