103	// Pending invoice items (prorations) of a subscription, moved onto an invoice.
104	export function takePending(state: State, sub: Subscription, invoice: string): Line[] {
105	  const out: Line[] = [];
106	  for (const ii of Object.values(state.invoice_items)) {
107	    if (ii.subscription !== sub.id || ii.invoice !== null) continue;
108	    ii.invoice = invoice;
109	    out.push({ ...ii.line, id: mint(state, "il") });
110	  }
111	  return out;
112	}
