114	function renew(state: State, sub: Subscription): void {
115	  const start = sub.period_end;
116	  const interval = priceOf(state, sub.items[0]?.price ?? "").interval;
117	  const end = periodAt(sub.anchor, interval, start)[1];
118	  const id = mint(state, "in");
119	  const pending = takePending(state, sub, id);
120	  const lines: Line[] = sub.items.map((it) => {
121	    const p = priceOf(state, it.price);
122	    return {
123	      id: mint(state, "il"),
124	      amount: p.unit_amount * it.quantity,
125	      description: recurringDescription(state, it.price, it.quantity),
126	      period: { start, end },
127	      price: it.price,
128	      quantity: it.quantity,
129	      proration: false,
130	      discountable: true,
131	      discount_amounts: [],
132	      subscription_item: it.id,
133	      invoice_item: null,
134	      credited: null,
135	      unit_amount_decimal: String(p.unit_amount),
136	    };
137	  });
138	  const active = sub.discounts.filter((d) => {
139	    const s = specOf(state, d);
140	    return s !== undefined && !(s.once && get(state.discounts, d)?.used === true);
141	  });
142	  const specs = specsOf(state, active);
143	  const alloc = allocate(
144	    lines.map((l) => l.amount),
145	    specs,
146	  );
147	  lines.forEach((l, i) => {
148	    l.discount_amounts = specs.map((s, k) => ({ discount: s.id, amount: alloc[k]?.[i] ?? 0 }));
149	  });
150	  spendOnce(state, specs, alloc);
151	  sub.items.forEach((it, i) => {
152	    const l = lines[i];
153	    if (l) it.billed = { invoice: id, line: l.id, amount: l.amount, discounts: l.discount_amounts };
154	  });
155	  const all = [...pending, ...lines];
156	  const inv: Invoice = {
157	    id,
158	    customer: sub.customer,
159	    subscription: sub.id,
160	    lines: all,
161	    discounts: specs.map((s) => s.id),
162	    total_discount_amounts: specs.map((s, k) => ({
163	      discount: s.id,
164	      amount: (alloc[k] ?? []).reduce((a, b) => a + b, 0),
165	    })),
166	    billing_reason: "subscription_cycle",
167	    status: "draft",
168	    created: start,
169	    period_start: sub.period_start,
170	    period_end: start,
171	    attempt_count: 0,
172	    amount_paid: 0,
173	    auto_advance: true,
174	    next_payment_attempt: start + HOUR,
175	    proration_date: null,
176	    retries: [],
177	    starting_balance: 0,
178	    deferred: 0,
179	  };
180	  // The customer balance moves onto the renewal invoice; a credit beyond its total stays.
181	  const cus = get(state.customers, sub.customer);
182	  if (cus) {
183	    inv.starting_balance = cus.balance;
184	    cus.balance = Math.min(0, invoiceTotal(inv) + cus.balance);
185	  }
186	  state.invoices[id] = inv;
187	  sub.latest_invoice = id;
188	  sub.period_start = start;
189	  sub.period_end = end;
190	  if (sub.status === "trialing") sub.status = "active";
191	}
192	
193	function attempt(state: State, inv: Invoice, at: number): void {
194	  const sub = inv.subscription ? get(state.subscriptions, inv.subscription) : undefined;
195	  const due = amountDue(inv);
196	  if (due === 0 || deferSmall(state, inv)) {
197	    inv.status = "paid";
198	    inv.next_payment_attempt = null;
199	    return;
200	  }
201	  inv.attempt_count += 1;
202	  if (!failing(state, inv.customer)) {
203	    inv.status = "paid";
204	    inv.amount_paid = due;
205	    inv.next_payment_attempt = null;
206	    if (sub?.status === "past_due") sub.status = "active";
207	    return;
208	  }
209	  inv.status = "open";
210	  if (inv.attempt_count === 1) inv.retries = RETRIES.map((d) => at + d);
211	  const next = inv.retries.shift();
212	  inv.next_payment_attempt = next ?? null;
213	  if (sub && sub.status !== "canceled") sub.status = "past_due";
214	}
