216	// Runs every event of the clock's customers up to `to`, in time order.
217	export function advanceClock(state: State, clock: Clock, to: number): void {
218	  const customers = new Set(
219	    Object.values(state.customers)
220	      .filter((c) => c.clock === clock.id)
221	      .map((c) => c.id),
222	  );
223	  for (let guard = 0; guard < 1000; guard += 1) {
224	    const events: { at: number; run: () => void }[] = [];
225	    const consider = (at: number, run: () => void): void => {
226	      if (at <= to) events.push({ at, run });
227	    };
228	    for (const sub of Object.values(state.subscriptions)) {
229	      if (!customers.has(sub.customer) || sub.status === "canceled") continue;
230	      const cancelAt = sub.cancel_at;
231	      if (cancelAt !== null && cancelAt <= sub.period_end) {
232	        consider(cancelAt, () => {
233	          sub.status = "canceled";
234	          sub.ended_at = cancelAt;
235	        });
236	        continue;
237	      }
238	      consider(sub.period_end, () => {
239	        if (sub.cancel_at_period_end) {
240	          sub.status = "canceled";
241	          sub.ended_at = sub.period_end;
242	        } else {
243	          renew(state, sub);
244	        }
245	      });
246	    }
247	    for (const inv of Object.values(state.invoices)) {
248	      if (!customers.has(inv.customer)) continue;
249	      if ((inv.status === "draft" && inv.auto_advance) || inv.status === "open") {
250	        const at = inv.next_payment_attempt;
251	        if (at !== null) {
252	          consider(at, () => {
253	            attempt(state, inv, at);
254	          });
255	        }
256	      }
257	    }
258	    // The earliest event first; ties keep discovery order (subscriptions before invoices).
259	    const chosen = events.reduce<{ at: number; run: () => void } | null>(
260	      (best, e) => (best === null || e.at < best.at ? e : best),
261	      null,
262	    );
263	    if (chosen === null) break;
264	    clock.frozen_time = Math.max(clock.frozen_time, chosen.at);
265	    chosen.run();
266	  }
267	  clock.frozen_time = to;
268	}
269	
270	export function cancelNow(
271	  state: State,
272	  sub: Subscription,
273	  prorate: boolean,
274	  invoiceNow: boolean,
275	): void {
276	  const now = nowFor(state, sub.customer);
277	  if (prorate && now < sub.period_end) {
278	    const credits = sub.items.map((it) => creditLine(state, sub, it, now).line);
279	    if (invoiceNow) {
280	      const id = mint(state, "in");
281	      const pending = takePending(state, sub, id);
282	      const lines: Line[] = [
283	        ...pending,
284	        ...credits.map((l) => ({ ...l, id: mint(state, "il"), invoice_item: mint(state, "ii") })),
285	      ];
286	      state.invoices[id] = {
287	        id,
288	        customer: sub.customer,
289	        subscription: sub.id,
